-- CAB-0007: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'CAB-0007: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('azalina-othman-said','zambry-abdul-kadir') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0007: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pengerang') and slug not in ('azalina-othman-said','zambry-abdul-kadir')) then raise exception 'CAB-0007: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0007:%' and (m.source_type <> 'editorial' or e.slug not in ('azalina-othman-said','zambry-abdul-kadir') or m.import_key not like 'CAB-0007:' || e.slug || ':%')) then raise exception 'CAB-0007: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'azalina-othman-said','Azalina Othman Said','government','Minister in the Prime Minister’s Department (Law and Institutional Reform)','Pengerang','Johor','Azalina Othman Said is Minister in the Prime Minister’s Department (Law and Institutional Reform). She represents Pengerang, Johor, in the Dewan Rakyat. She is a member of UMNO.','https://www.bheuu.gov.my/','/portraits/azalina-othman-said.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P157.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Pengerang", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4196"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'zambry-abdul-kadir','Zambry Abdul Kadir','government','Minister of Higher Education',null,null,'Zambry Abdul Kadir is Minister of Higher Education. He serves as a senator appointed by the Yang di-Pertuan Agong. He is a member of UMNO.','https://www.mohe.gov.my/','/portraits/zambry-abdul-kadir.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/Zambry2.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Dewan Negara", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dn&id=4034"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('azalina-othman-said','zambry-abdul-kadir') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0007: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0007:azalina-othman-said:freedom-information-bill','Develop and table a Freedom of Information Bill','Governance','in_progress',null,null,'2026-08-03','https://www.bernama.com/en/news.php/?id=2589631','2026-09-07','https://www.bernama.com/en/news.php?id=2604269','Azalina said a parliamentary select committee would scrutinise the proposed Freedom of Information Bill before its tabling.','Her September update describes committee deliberations and planned public consultation. This supports ongoing development, not enactment or operation of an access-to-information law. A final delivery date and completion percentage were not established.','2026-11-09','editorial',false from public.entities e where e.slug='azalina-othman-said' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW